-- Dumping structure for view db_maintenance.view_admin_report
DROP VIEW IF EXISTS `view_admin_report`;
-- Creating temporary table to overcome VIEW dependency errors
CREATE TABLE `view_admin_report` (
	`ID Tiket` BIGINT(20) NOT NULL,
	`Status Terkini` VARCHAR(1) NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Waktu Lapor` VARCHAR(1) NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Nama Mesin` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Nama Operator` VARCHAR(1) NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Jenis Problem` MEDIUMTEXT NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Deskripsi Detail` MEDIUMTEXT NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Nomor Aplikator` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Penyebab Masalah` MEDIUMTEXT NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Tindakan Perbaikan` MEDIUMTEXT NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Nama Teknisi` VARCHAR(1) NULL COLLATE 'utf8mb4_uca1400_ai_ci',
	`Tunggu Teknisi` TIME NULL,
	`Durasi Perbaikan` TIME NULL,
	`Tunggu Part` TIME NULL,
	`Tunggu Inspect` TIME NULL,
	`Tunggu Operator` TIME NULL,
	`Total Downtime` TIME NULL,
	`Nilai Kinerja (GL)` INT(11) NULL,
	`Nilai Pemakaian (Operator)` INT(11) NULL
);

-- Removing temporary table and create final VIEW structure
DROP TABLE IF EXISTS `view_admin_report`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_admin_report` AS SELECT 
    t.ticket_id AS 'ID Tiket',
    
    -- ═══ [KOLOM STATUS YANG HILANG SUDAH DIKEMBALIKAN] ═══
    ts.status_name AS 'Status Terkini',
    -- ═════════════════════════════════════════════════════
    
    DATE_FORMAT(t.created_at, '%d %b %Y %H:%i') AS 'Waktu Lapor',
    CONCAT(IFNULL(mt.type_name, ''), '-', IFNULL(ma.area_name, ''), '.', IFNULL(m.machine_number, '')) AS 'Nama Mesin',
    u_op.full_name AS 'Nama Operator',
    
    -- 1. Jenis Problem (Dipisah dengan Enter)
    (SELECT GROUP_CONCAT(IFNULL(pt.type_name, tp.problem_type_remarks) SEPARATOR '
')
     FROM ticket_problems tp
     LEFT JOIN problem_types pt ON tp.problem_type_id = pt.type_id
     WHERE tp.ticket_id = t.ticket_id
    ) AS 'Jenis Problem',

    -- 2. Deskripsi Detail (Dipisah dengan Enter)
    (SELECT GROUP_CONCAT(IFNULL(f.failure_name, tp.failure_remarks) SEPARATOR '
')
     FROM ticket_problems tp
     LEFT JOIN failures f ON tp.failure_id = f.failure_id
     WHERE tp.ticket_id = t.ticket_id
    ) AS 'Deskripsi Detail',

    -- 3. Nomor Aplikator (Langsung dari tabel tickets)
    IFNULL(t.applicator_code, '-') AS 'Nomor Aplikator',

    -- 4. Penyebab Masalah (Dipisah dengan Enter)
    (SELECT GROUP_CONCAT(IFNULL(fc.cause_name, tp.root_cause_remarks) SEPARATOR '
')
     FROM ticket_problems tp
     LEFT JOIN failure_causes fc ON tp.root_cause_id = fc.cause_id
     WHERE tp.ticket_id = t.ticket_id
    ) AS 'Penyebab Masalah',

    -- 5. Tindakan Perbaikan (Dipisah dengan Enter)
    (SELECT GROUP_CONCAT(IFNULL(act.action_name, tp.action_details_manual) SEPARATOR '
')
     FROM ticket_problems tp
     LEFT JOIN actions act ON tp.action_id = act.action_id
     WHERE tp.ticket_id = t.ticket_id
    ) AS 'Tindakan Perbaikan',

    u_tech.full_name AS 'Nama Teknisi',
    
    -- KPI WAKTU
    SEC_TO_TIME(IFNULL(t.arrival_elapsed_seconds, IFNULL(TIME_TO_SEC(TIMEDIFF(t.started_at, t.created_at)), 0))) AS 'Tunggu Teknisi',
    SEC_TO_TIME(IFNULL(t.repair_elapsed_seconds, IFNULL(TIME_TO_SEC(TIMEDIFF(t.technician_finished_at, t.started_at)), 0))) AS 'Durasi Perbaikan',
    
    (SELECT SEC_TO_TIME(IFNULL(SUM(TIME_TO_SEC(TIMEDIFF(pr.ready_at, pr.requested_at))), 0)) 
     FROM part_requests pr 
     WHERE pr.ticket_id = t.ticket_id AND pr.ready_at IS NOT NULL
    ) AS 'Tunggu Part',

    SEC_TO_TIME(IFNULL(t.inspection_elapsed_seconds, 0)) AS 'Tunggu Inspect',
    TIMEDIFF(t.production_resumed_at, t.technician_finished_at) AS 'Tunggu Operator',
    TIMEDIFF(t.production_resumed_at, t.created_at) AS 'Total Downtime',
    
    t.gl_rating_score AS 'Nilai Kinerja (GL)',
    t.tech_rating_score AS 'Nilai Pemakaian (Operator)'

FROM tickets t
-- ═══ [JOIN TABEL STATUS] ═══
LEFT JOIN ticket_statuses ts ON t.status_id = ts.status_id
-- ═══════════════════════════
LEFT JOIN machines m ON t.machine_id = m.machine_id
LEFT JOIN machine_types mt ON m.type_id = mt.type_id
LEFT JOIN machine_areas ma ON m.area_id = ma.area_id
LEFT JOIN users u_op ON t.operator_id = u_op.user_id
LEFT JOIN users u_tech ON t.technician_id = u_tech.user_id 
;


CREATE TABLE IF NOT EXISTS `micrometer_patrols` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `patrol_date` DATE NOT NULL,
  `shift` VARCHAR(10) NOT NULL,
  `user_id` INT(11) NOT NULL COMMENT 'Bisa Operator atau Teknisi',
  `micrometer_id` VARCHAR(50) NOT NULL COMMENT 'Nomor seri atau kode mikrometer',
  `standard_value` DECIMAL(10,3) NOT NULL COMMENT 'Nilai standar blok',
  `actual_value` DECIMAL(10,3) NOT NULL COMMENT 'Nilai ukur aktual',
  `judgment` ENUM('OK', 'NG') NOT NULL,
  `notes` TEXT DEFAULT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `FK_micrometer_user` (`user_id`),
  CONSTRAINT `FK_micrometer_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;


